import{_ as o,o as a,c as s,a7 as t}from"./chunks/framework.CULO68qY.js";const h=JSON.parse('{"title":"Configuration","description":"Overview of the Axolotl-PM configuration files, including server.properties, pocketmine.yml, resource_packs.yml, and the op and ban lists.","frontmatter":{"title":"Configuration","outline":"deep","description":"Overview of the Axolotl-PM configuration files, including server.properties, pocketmine.yml, resource_packs.yml, and the op and ban lists.","head":[["link",{"rel":"canonical","href":"https://axolotl-pm.org/docs/configuration"}]]},"headers":[],"relativePath":"docs/configuration.md","filePath":"docs/configuration.md","lastUpdated":null}'),i={name:"docs/configuration.md"};function r(n,e,c,l,d,p){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><h2 id="server-behaviour" tabindex="-1">Server behaviour <a class="header-anchor" href="#server-behaviour" aria-label="Permalink to &quot;Server behaviour&quot;">​</a></h2><p>Axolotl-PM’s behaviour is controlled by several configuration files. You can edit them to change the behaviour of your server.</p><ul><li><code>server.properties</code> contains basic settings like the server name, port, maximum view distance, etc. These settings are all safe to change.</li><li><code>pocketmine.yml</code> contains more advanced settings like memory usage, max thread count, etc. It also contains settings for loading multiple worlds.</li></ul><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>It’s best to <strong>leave a setting alone</strong> if you don’t understand what it’s for. Many settings in <code>pocketmine.yml</code> can break your server if configured incorrectly.</p></div><div class="info custom-block"><p class="custom-block-title">Note</p><p>To edit configs on Windows, right-click on the file → Open With → Choose another app → Notepad.</p></div><h2 id="resource-packs" tabindex="-1">Resource packs <a class="header-anchor" href="#resource-packs" aria-label="Permalink to &quot;Resource packs&quot;">​</a></h2><p><code>resource_packs.yml</code> is found in the <code>resource_packs</code> folder.</p><p><a href="/website/previews/vitepress-native-0137662/docs/resourcepacks">Read more about installing resource packs.</a></p><h2 id="player-permissions" tabindex="-1">Player permissions <a class="header-anchor" href="#player-permissions" aria-label="Permalink to &quot;Player permissions&quot;">​</a></h2><p>There are several files that allow you to control player permissions on your server:</p><ul><li><code>ops.txt</code> is a simple list of player names that have “op” permissions on your server. Ops can do more things than regular players, like giving items, teleporting, stopping the server and more.</li><li><code>banned-players.txt</code> lists names of players that are banned from your server.</li><li><code>banned-ips.txt</code> lists IPs that are not allowed to connect to your server. This is useful for troublesome players who change accounts and keep coming back to hassle you.</li></ul><div class="info custom-block"><p class="custom-block-title">Note</p><p>You can modify these by using slash commands instead of editing the files directly. See <code>/op</code>, <code>/deop</code>, <code>/ban</code>, <code>/unban</code>, <code>/ban-ip</code> and <code>/unban-ip</code>.</p></div>',13)])])}const m=o(i,[["render",r]]);export{h as __pageData,m as default};
